(function(){const dialog=document.querySelector("dialog");const trigger=document.querySelector("[data-about]");if(!dialog||!trigger||typeof dialog.showModal!=="function")return;trigger.setAttribute("aria-haspopup","dialog");trigger.addEventListener("click",event=>{if(event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();dialog.showModal()});dialog.querySelector("button").addEventListener("click",()=>dialog.close());dialog.addEventListener("close",()=>trigger.focus({preventScroll:true}))})();
